<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{api,errorMessage}from'../lib/api';import StatusBadge from'../components/StatusBadge.vue';const route=useRoute(),order=ref<any>(),error=ref('');onMounted(async()=>{try{order.value=(await api.get(`/orders/${route.params.id}`)).data.data}catch(e){error.value=errorMessage(e)}})</script>
<template><div v-if="error" class="form-error">{{error}}</div><template v-if="order"><div class="page-heading"><div><p class="eyebrow">ORDER {{order.id.slice(0,8).toUpperCase()}}</p><h1>{{order.request.listing.title}}</h1><p>{{order.buyerOrganization.name}} → {{order.sellerOrganization.name}}</p></div><StatusBadge :status="order.status"/></div><div class="dashboard-grid"><article class="panel"><h3>Order details</h3><div class="detail-list"><p><span>Quantity</span><strong>{{order.request.quantity}}</strong></p><p><span>Total</span><strong>{{Number(order.totalAmount).toLocaleString()}} {{order.currency}}</strong></p><p><span>Destination</span><strong>{{order.request.destinationLocation.name}}</strong></p><p><span>Created</span><strong>{{new Date(order.createdAt).toLocaleString()}}</strong></p></div></article><article class="panel"><h3>Status timeline</h3><ol class="timeline"><li v-for="h in order.statusHistory" :key="h.id"><span/><div><strong>{{h.toStatus.replaceAll('_',' ')}}</strong><small>{{new Date(h.createdAt).toLocaleString()}}</small></div></li></ol></article></div></template></template>
